 const [categories,setCategories]=useState<Category[]>([]),[customers,setCustomers]=useState<Customer[]>([]),[branches,setBranches]=useState<Branch[]>([]),[warehouses,setWarehouses]=useState<Warehouse[]>([]),[locations,setLocations]=useState<WarehouseLocation[]>([]),[refs,setRefs]=useState<Ref[]>([]),[products,setProducts]=useState<Product[]>([]);
