 const emptyProduct={sku:'',name:'',description:'',barcode:'',categoryId:'',brandCode:'',unit:'',productType:'PHYSICAL',taxCategoryCode:'',trackBatch:false,trackExpiry:false,trackSerial:false,allowNegativeStock:false,costPrice:0,salePrice:0,retailCeilingPrice:'',minStock:0,isActive:true};
