 async function saveWarehouse(e:FormEvent){e.preventDefault();try{const path=editingWarehouseId?`/master-data/warehouses/${editingWarehouseId}`:'/master-data/warehouses';const method=editingWarehouseId?'PATCH':'POST';await call(token,path,{method,body:JSON.stringify({branchId:wh.branchId,code:wh.code,name:wh.name,address:wh.address||undefined,isDefault:wh.isDefault})});setMsg(editingWarehouseId?'Gudang diperbarui.':'Gudang dibuat.');setEditingWarehouseId(null);setWh(v=>({branchId:v.branchId,code:'',name:'',address:'',isDefault:false}));await refresh();}catch(e){setMsg(e instanceof Error?e.message:'Gagal menyimpan gudang');}}
