 useEffect(()=>{const ids=[variantForm.productId,unitForm.productId,barcode.productId,price.productId].filter(Boolean);for(const id of [...new Set(ids)]){void loadVariants(id);void loadUnits(id);void loadBarcodes(id);void loadPrices(id);void loadPriceHistory(id);}},[token,variantForm.productId,unitForm.productId,barcode.productId,price.productId]);
