 async function saveProduct(e:FormEvent){e.preventDefault();setMsg('');const body={...productForm,sku:productForm.sku.trim(),name:productForm.name.trim(),description:productForm.description.trim()||undefined,barcode:productForm.barcode.trim()||undefined,categoryId:productForm.categoryId||undefined,brandCode:productForm.brandCode.trim()||undefined,unit:productForm.unit.trim().toUpperCase(),taxCategoryCode:productForm.taxCategoryCode.trim()||undefined,costPrice:Number(productForm.costPrice),salePrice:Number(productForm.salePrice),retailCeilingPrice:productForm.retailCeilingPrice===''?undefined:Number(productForm.retailCeilingPrice),minStock:Number(productForm.minStock)};try{await call(token,editingProductId?`/products/${editingProductId}`:'/products',{method:editingProductId?'PATCH':'POST',body:JSON.stringify(body)});setEditingProductId(null);setProductForm(emptyProduct);await refresh();setMsg(editingProductId?'Perubahan produk tersimpan.':'Produk berhasil dibuat.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal menyimpan produk');}}
