 async function saveVariant(e:FormEvent){e.preventDefault();if(!variantForm.productId)return;setMsg('');let attributes:Record<string,unknown>|undefined;try{attributes=variantForm.attributes.trim()?JSON.parse(variantForm.attributes):undefined;}catch{setMsg('Attributes variant harus JSON valid.');return;}const body={code:variantForm.code.trim(),sku:variantForm.sku.trim()||undefined,name:variantForm.name.trim(),attributes,costPrice:variantForm.costPrice===''?undefined:Number(variantForm.costPrice),salePrice:variantForm.salePrice===''?undefined:Number(variantForm.salePrice),isDefault:variantForm.isDefault,isActive:variantForm.isActive};try{const productId=variantForm.productId;await call(token,editingVariantId?`/master-data/products/${productId}/variants/${editingVariantId}`:`/master-data/products/${productId}/variants`,{method:editingVariantId?'PATCH':'POST',body:JSON.stringify(body)});setEditingVariantId(null);setVariantForm({...emptyVariant,productId});await loadVariants(productId);setMsg('Variant produk tersimpan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal menyimpan variant');}}
