 async function toggleReference(row:Ref){try{await call(token,`/master-data/references/${row.id}`,{method:'PATCH',body:JSON.stringify({isActive:!row.isActive})});await refresh();setMsg(row.isActive?'Reference dinonaktifkan.':'Reference diaktifkan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal mengubah status reference');}}
 async function saveBarcode(e:FormEvent){e.preventDefault();if(!barcode.productId)return;setMsg('');const body={variantId:barcode.variantId||undefined,productUnitId:barcode.productUnitId||undefined,code:barcode.code.trim(),isPrimary:barcode.isPrimary,unitCode:barcode.unitCode||selectedBarcodeProduct?.unit,quantityFactor:Number(barcode.quantityFactor)};try{const productId=barcode.productId;await call(token,editingBarcodeId?`/master-data/products/${productId}/barcodes/${editingBarcodeId}`:`/master-data/products/${productId}/barcodes`,{method:editingBarcodeId?'PATCH':'POST',body:JSON.stringify(body)});setEditingBarcodeId(null);setBarcode(v=>({...v,code:'',quantityFactor:1,isPrimary:false}));await Promise.all([loadBarcodes(productId),refresh()]);setMsg('Barcode produk tersimpan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal menyimpan barcode');}}
 function editBarcode(row:ProductBarcode){setEditingBarcodeId(row.id);setBarcode({productId:row.productId,variantId:row.variantId??'',productUnitId:row.productUnitId??'',code:row.code,unitCode:row.unitCode??'',quantityFactor:Number(row.quantityFactor),isPrimary:row.isPrimary});}
 async function savePrice(e:FormEvent){e.preventDefault();if(!price.productId)return;setMsg('');const body={variantId:price.variantId||undefined,productUnitId:price.productUnitId||undefined,branchId:price.branchId||undefined,segmentCode:price.segmentCode.trim()||'RETAIL',unitCode:price.unitCode||selectedPriceProduct?.unit,minQty:Number(price.minQty),price:Number(price.price),effectiveFrom:price.effectiveFrom||undefined,effectiveTo:price.effectiveTo||undefined,...(editingPriceId?{isActive:price.isActive}:{})};try{const productId=price.productId;await call(token,editingPriceId?`/master-data/products/${productId}/prices/${editingPriceId}`:`/master-data/products/${productId}/prices`,{method:editingPriceId?'PATCH':'POST',body:JSON.stringify(body)});setEditingPriceId(null);setPrice(v=>({...v,minQty:1,price:0,effectiveFrom:'',effectiveTo:'',isActive:true}));await Promise.all([loadPrices(productId),loadPriceHistory(productId)]);setMsg('Harga produk tersimpan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal menyimpan harga');}}
 function editPrice(row:ProductPrice){setEditingPriceId(row.id);setPrice({productId:row.productId,variantId:row.variantId??'',productUnitId:row.productUnitId??'',branchId:row.branchId??'',segmentCode:row.segmentCode,unitCode:row.unitCode??'',minQty:Number(row.minQty),price:Number(row.price),effectiveFrom:row.effectiveFrom?.slice(0,10)??'',effectiveTo:row.effectiveTo?.slice(0,10)??'',isActive:row.isActive});}
 async function togglePrice(row:ProductPrice){try{await call(token,`/master-data/products/${row.productId}/prices/${row.id}`,{method:'PATCH',body:JSON.stringify({isActive:!row.isActive})});await loadPrices(row.productId);setMsg(row.isActive?'Harga dinonaktifkan.':'Harga diaktifkan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal mengubah status harga');}}

 function categoryLabel(category:Category){const names=[category.name];const seen=new Set<string>([category.id]);let parentId=category.parentId??null;while(parentId){const parent=categories.find(item=>item.id===parentId);if(!parent||seen.has(parent.id))break;names.unshift(parent.name);seen.add(parent.id);parentId=parent.parentId??null;}return names.join(' › ');}
 function categoryTreeRows(){const byParent=new Map<string,Category[]>();for(const category of categories){const key=category.parentId??'';const rows=byParent.get(key)??[];rows.push(category);byParent.set(key,rows);}for(const rows of byParent.values())rows.sort((a,b)=>Number(a.sortOrder??0)-Number(b.sortOrder??0)||a.name.localeCompare(b.name,'id'));const ordered:Array<{category:Category;depth:number}>=[];const seen=new Set<string>();const visit=(parentId:string,depth:number)=>{for(const category of byParent.get(parentId)??[]){if(seen.has(category.id))continue;seen.add(category.id);ordered.push({category,depth});visit(category.id,depth+1);}};visit('',0);for(const category of categories){if(!seen.has(category.id))ordered.push({category,depth:0});}return ordered;}
 const orderedCategoryRows=categoryTreeRows();
 const rootCategoryCount=categories.filter(category=>!category.parentId).length;
 const subcategoryCount=categories.length-rootCategoryCount;
 const categoryProductCount=categories.reduce((total,category)=>total+Number(category._count?.products??0),0);
 function focusCategoryForm(){requestAnimationFrame(()=>{categoryFormRef.current?.scrollIntoView({behavior:'smooth',block:'start'});categoryFormRef.current?.querySelector<HTMLInputElement>('input[name="category-name"]')?.focus();});}
 function beginCategory(parentId=''){setEditingCategoryId(null);setCategoryForm({...emptyCategory,parentId});focusCategoryForm();}
 async function saveCategory(e:FormEvent){e.preventDefault();setMsg('');const body={name:categoryForm.name.trim(),slug:categoryForm.slug.trim()||undefined,parentId:categoryForm.parentId||undefined,sortOrder:Number(categoryForm.sortOrder),isActive:categoryForm.isActive};try{const wasEditing=Boolean(editingCategoryId);const wasSubcategory=Boolean(categoryForm.parentId);await call(token,editingCategoryId?`/master-data/categories/${editingCategoryId}`:'/master-data/categories',{method:editingCategoryId?'PATCH':'POST',body:JSON.stringify(body)});setEditingCategoryId(null);setCategoryForm(emptyCategory);await refresh();setMsg(wasEditing?'Perubahan kategori tersimpan.':wasSubcategory?'Subkategori berhasil dibuat.':'Kategori utama berhasil dibuat.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal menyimpan kategori');}}
 function editCategory(category:Category){setEditingCategoryId(category.id);setCategoryForm({name:category.name,slug:category.slug,parentId:category.parentId??'',sortOrder:Number(category.sortOrder??0),isActive:category.isActive!==false});focusCategoryForm();}
 async function toggleCategory(category:Category){setMsg('');try{await call(token,`/master-data/categories/${category.id}`,{method:'PATCH',body:JSON.stringify({isActive:!category.isActive})});if(editingCategoryId===category.id){setEditingCategoryId(null);setCategoryForm(emptyCategory);}await refresh();setMsg(category.isActive?'Kategori dinonaktifkan.':'Kategori diaktifkan.');}catch(err){setMsg(err instanceof Error?err.message:'Gagal mengubah status kategori');}}

 return <>
  {(!mode || mode==='catalog') && <section className="masterCatalogLayout">
   <Panel eyebrow="KATALOG PRODUK" title="Kategori & Subkategori" badge={`${categories.length} kategori`}>
    <div className="catalogSummary" aria-label="Ringkasan kategori"><div className="catalogStat"><span>Kategori utama</span><strong>{rootCategoryCount}</strong></div><div className="catalogStat"><span>Subkategori</span><strong>{subcategoryCount}</strong></div><div className="catalogStat"><span>Produk terhubung</span><strong>{categoryProductCount}</strong></div></div>
    <div className="actionRow categoryPrimaryActions">{canManageMasterData&&<button type="button" onClick={()=>beginCategory('')}>Tambah kategori utama</button>}<span className="sectionHelp">Tambah subkategori langsung dari baris parent agar hierarchy tidak membingungkan.</span></div>
    <div className="catalogFormShell"><div className="catalogFormHeader"><div><span className="eyebrow">{editingCategoryId?'EDIT KATEGORI':categoryForm.parentId?'SUBKATEGORI BARU':'KATEGORI BARU'}</span><h3>{editingCategoryId?'Perbarui struktur kategori':categoryForm.parentId?`Tambah subkategori di ${categories.find(x=>x.id===categoryForm.parentId)?.name??'kategori terpilih'}`:'Tambah kategori utama'}</h3></div>{(editingCategoryId||categoryForm.parentId)&&<button type="button" className="secondary" onClick={()=>beginCategory('')}>Reset ke kategori utama</button>}</div><form ref={categoryFormRef} className="formStack" onSubmit={e=>void saveCategory(e)}><label>Nama kategori<input name="category-name" required value={categoryForm.name} onChange={e=>setCategoryForm({...categoryForm,name:e.target.value})}/></label><label>Slug<input value={categoryForm.slug} onChange={e=>setCategoryForm({...categoryForm,slug:e.target.value})} placeholder="Otomatis dari nama bila kosong"/></label><label>Parent kategori<select value={categoryForm.parentId} onChange={e=>setCategoryForm({...categoryForm,parentId:e.target.value})}><option value="">Root / kategori utama</option>{categories.filter(x=>x.isActive&&x.id!==editingCategoryId).map(x=><option key={x.id} value={x.id}>{categoryLabel(x)}</option>)}</select></label><label>Urutan dalam parent<input type="number" min="0" step="1" value={categoryForm.sortOrder} onChange={e=>setCategoryForm({...categoryForm,sortOrder:Math.max(0,Math.floor(Number(e.target.value)||0))})}/></label><label className="checkboxRow"><input type="checkbox" checked={categoryForm.isActive} onChange={e=>setCategoryForm({...categoryForm,isActive:e.target.checked})}/> Kategori aktif</label><div className="actionRow">{canManageMasterData&&<button>{editingCategoryId?'Simpan perubahan':categoryForm.parentId?'Simpan subkategori':'Simpan kategori utama'}</button>}{editingCategoryId&&<button type="button" className="secondary" onClick={()=>beginCategory('')}>Batal edit</button>}</div></form></div>
    <Table head={['Struktur','Slug','Produk','Status','Aksi']} rows={orderedCategoryRows.map(({category:x,depth})=>[<span className="categoryHierarchyName" style={{paddingLeft:`${Math.min(depth,6)*18}px`}}><span className="categoryDepthBadge">{depth===0?'UTAMA':`L${depth}`}</span><strong>{x.name}</strong>{Number(x._count?.children??0)>0&&<small>{x._count?.children} subkategori</small>}</span>,x.slug,String(x._count?.products??0),<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>beginCategory(x.id)} disabled={!x.isActive}>Tambah subkategori</button><button type="button" className="secondary" onClick={()=>editCategory(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleCategory(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada kategori"/>
   </Panel>
  </section>}
  {(!mode || mode==='customers') && <section className="masterCatalogLayout"><Panel eyebrow="PELANGGAN" title={editingCustomerId?'Edit Customer':'Customer Master'} badge={`${customers.length} customer`}><p className="sectionHelp">Customer tenant-scoped lengkap dengan kontak, alamat, segmen, dan NPWP/tax identifier.</p><form className="formStack" onSubmit={e=>void saveCustomer(e)}><div className="formGrid"><label>Nama<input required value={cust.name} onChange={e=>setCust({...cust,name:e.target.value})}/></label><label>Segmen<input value={cust.customerType} onChange={e=>setCust({...cust,customerType:e.target.value})}/></label></div><div className="formGrid"><label>Telepon<input value={cust.phone} onChange={e=>setCust({...cust,phone:e.target.value})}/></label><label>Email<input type="email" value={cust.email} onChange={e=>setCust({...cust,email:e.target.value})}/></label></div><label>Alamat<textarea value={cust.address} onChange={e=>setCust({...cust,address:e.target.value})}/></label><label>Tax ID / NPWP<input value={cust.taxIdNumber} onChange={e=>setCust({...cust,taxIdNumber:e.target.value})}/></label><div className="actionRow">{canManageCustomers&&<button>{editingCustomerId?'Simpan perubahan':'Simpan pelanggan'}</button>}{editingCustomerId&&<button type="button" className="secondary" onClick={()=>{setEditingCustomerId(null);setCust({name:'',phone:'',email:'',address:'',customerType:'RETAIL',taxIdNumber:''});}}>Batal</button>}</div></form><Table head={['Nama','Kontak','Segmen','Tax ID','Aksi']} rows={customers.slice(0,50).map(x=>[<strong>{x.name}</strong>,<span>{x.phone||x.email||'-'}<small>{x.address||''}</small></span>,x.customerType,x.taxIdNumber||'-',canManageCustomers?<button type="button" className="secondary" onClick={()=>editCustomer(x)}>Edit</button>:null])} empty="Belum ada pelanggan"/></Panel></section>}
  <section className="grid2">
   {(!mode || mode==='organization') && <Panel eyebrow="ORGANISASI" title="Cabang & Gudang"><form className="formStack" onSubmit={e=>void saveWarehouse(e)}><label>Cabang<select required value={wh.branchId} onChange={e=>setWh({...wh,branchId:e.target.value})}>{branches.map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><label>Kode gudang<input required value={wh.code} onChange={e=>setWh({...wh,code:e.target.value})}/></label><label>Nama gudang<input required value={wh.name} onChange={e=>setWh({...wh,name:e.target.value})}/></label><label>Alamat<input value={wh.address} onChange={e=>setWh({...wh,address:e.target.value})}/></label><label className="checkRow"><input type="checkbox" checked={wh.isDefault} onChange={e=>setWh({...wh,isDefault:e.target.checked})}/> Gudang default cabang</label><div className="actionRow">{canManageMasterData&&<button>{editingWarehouseId?'Simpan perubahan':'Simpan gudang'}</button>}{editingWarehouseId&&<button type="button" className="secondary" onClick={()=>{setEditingWarehouseId(null);setWh(v=>({branchId:v.branchId,code:'',name:'',address:'',isDefault:false}));}}>Batal</button>}</div></form><Table head={['Cabang','Kode','Nama','Default','Status','Aksi']} rows={warehouses.map(x=>[x.branch?<>{x.branch.code} · {x.branch.name}</>:'-',<strong>{x.code}</strong>,x.name,x.isDefault?'YA':'-',<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editWarehouse(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleWarehouse(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada gudang"/><p className="sectionHelp">Gudang dikelola dinamis per cabang. Edit dan lifecycle menggunakan endpoint tenant-scoped yang sama dengan create.</p></Panel>}
   {(!mode || mode==='locations') && <Panel eyebrow="LOKASI GUDANG" title={editingLocationId?'Edit Zone / Rack / Bin':'Zone / Rack / Bin'}><form className="formStack" onSubmit={e=>void saveLocation(e)}><label>Gudang<select required value={location.warehouseId} onChange={e=>setLocation({...location,warehouseId:e.target.value,parentId:''})}>{warehouses.map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><label>Parent lokasi<select value={location.parentId} onChange={e=>setLocation({...location,parentId:e.target.value})}><option value="">Tidak ada / root</option>{locations.filter(x=>x.warehouseId===location.warehouseId&&x.isActive&&x.id!==editingLocationId).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><div className="formGrid"><label>Tipe<select value={location.type} onChange={e=>setLocation({...location,type:e.target.value})}>{['ZONE','AISLE','RACK','BIN'].map(x=><option key={x}>{x}</option>)}</select></label><label>Kode<input required value={location.code} onChange={e=>setLocation({...location,code:e.target.value})}/></label></div><label>Nama<input required value={location.name} onChange={e=>setLocation({...location,name:e.target.value})}/></label><div className="formGrid"><label>Barcode lokasi<input value={location.barcode} onChange={e=>setLocation({...location,barcode:e.target.value})}/></label><label>Kapasitas<input type="number" min="0" value={location.capacity} onChange={e=>setLocation({...location,capacity:e.target.value})}/></label></div>{editingLocationId&&<label className="checkboxRow"><input type="checkbox" checked={location.isActive} onChange={e=>setLocation({...location,isActive:e.target.checked})}/> Lokasi aktif</label>}<div className="actionRow">{canManageMasterData&&<button>{editingLocationId?'Simpan perubahan':'Simpan lokasi'}</button>}{editingLocationId&&<button type="button" className="secondary" onClick={()=>{setEditingLocationId(null);setLocation(v=>({...v,parentId:'',code:'',name:'',barcode:'',capacity:'',isActive:true}));}}>Batal</button>}</div></form><Table head={['Gudang','Kode','Nama','Tipe','Status','Aksi']} rows={locations.slice(0,40).map(x=>[warehouses.find(w=>w.id===x.warehouseId)?.code??'-',<strong>{x.code}</strong>,x.name,x.type,<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editLocation(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleLocation(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada lokasi gudang"/></Panel>}
   {(!mode || mode==='references') && <Panel eyebrow="REFERENCE MASTER" title={editingRefId?'Edit Reference':'Brand, Unit, Bank, Courier, Payment'}><form className="formStack" onSubmit={e=>void saveReference(e)}><label>Tipe<select disabled={Boolean(editingRefId)} value={ref.type} onChange={e=>setRef(emptyRef(e.target.value))}>{['BRAND','UNIT','BANK','COURIER','PAYMENT_METHOD'].map(x=><option key={x}>{x}</option>)}</select></label><label>Kode<input disabled={Boolean(editingRefId)} required value={ref.code} onChange={e=>setRef({...ref,code:e.target.value.toUpperCase()})}/></label><label>Nama<input required value={ref.name} onChange={e=>setRef({...ref,name:e.target.value})}/></label>{ref.type!=='UNIT'&&<label>Cakupan cabang<select value={ref.branchId} onChange={e=>setRef({...ref,branchId:e.target.value})}><option value="">Semua cabang</option>{branches.filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label>}{ref.type==='PAYMENT_METHOD'&&<><label>Jenis tender<select value={ref.tenderKind} onChange={e=>setRef({...ref,tenderKind:e.target.value,allowCashChange:e.target.value==='CASH'?ref.allowCashChange:false})}><option value="CASH">Kas fisik</option><option value="SETTLEMENT">Settlement / clearing</option></select></label><label>Akun settlement<input required value={ref.settlementAccountCode} onChange={e=>setRef({...ref,settlementAccountCode:e.target.value})} placeholder="1101 / 1102 / akun aset lain"/></label><label>Perilaku settlement<select value={ref.settlementBehavior} onChange={e=>setRef({...ref,settlementBehavior:e.target.value})}><option value="IMMEDIATE">Immediate</option><option value="CLEARING">Clearing</option></select></label><label>Refund<select value={ref.refundBehavior} onChange={e=>setRef({...ref,refundBehavior:e.target.value})}><option value="ORIGINAL">Ke tender asal</option><option value="CASH">Ke kas</option><option value="SETTLEMENT">Ke akun settlement</option><option value="RECEIVABLE">Kurangi piutang</option><option value="DISABLED">Tidak dapat direfund</option></select></label>{ref.refundBehavior==='CASH'&&<label>Akun refund<input required value={ref.refundAccountCode} onChange={e=>setRef({...ref,refundAccountCode:e.target.value})} placeholder="1101"/></label>}<label>Akun fee<input value={ref.feeAccountCode} onChange={e=>setRef({...ref,feeAccountCode:e.target.value})} placeholder="Kosong bila fee 0"/></label><label>Fee (%)<input type="number" min="0" max="100" step="0.01" value={ref.feeRatePercent} onChange={e=>setRef({...ref,feeRatePercent:Math.max(0,Number(e.target.value)||0)})}/></label><label className="checkboxRow"><input type="checkbox" checked={ref.requiresProvider} onChange={e=>setRef({...ref,requiresProvider:e.target.checked})}/> Provider wajib</label><label className="checkboxRow"><input type="checkbox" checked={ref.requiresReference} onChange={e=>setRef({...ref,requiresReference:e.target.checked})}/> Referensi eksternal wajib</label><label className="checkboxRow"><input type="checkbox" checked={ref.allowOffline} onChange={e=>setRef({...ref,allowOffline:e.target.checked})}/> Boleh offline</label><label className="checkboxRow"><input type="checkbox" disabled={ref.tenderKind!=='CASH'} checked={ref.allowCashChange} onChange={e=>setRef({...ref,allowCashChange:e.target.checked})}/> Boleh kembalian tunai</label></>}{editingRefId&&<label className="checkboxRow"><input type="checkbox" checked={ref.isActive} onChange={e=>setRef({...ref,isActive:e.target.checked})}/> Reference aktif</label>}<div className="actionRow">{canManageMasterData&&<button>{editingRefId?'Simpan perubahan':'Simpan referensi'}</button>}{editingRefId&&<button type="button" className="secondary" onClick={()=>{setEditingRefId(null);setRef(emptyRef(ref.type));}}>Batal</button>}</div></form><Table head={['Tipe','Kode','Nama','Konfigurasi','Status','Aksi']} rows={refs.slice(0,50).map(x=>[x.type,<strong>{x.code}</strong>,x.name,x.type==='PAYMENT_METHOD'?`${String(x.metadata?.kind??'-')} · ${String(x.metadata?.settlementAccountCode??'-')} · refund ${String(x.metadata?.refundBehavior??'-')}`:(x.branchId?branches.find(b=>b.id===x.branchId)?.code??'Cabang':'Global'),<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editReference(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleReference(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada reference master"/></Panel>}
  </section>
  <section className="grid2">
   {(!mode || mode==='products') && <Panel eyebrow="MASTER PRODUK" title={editingProductId?'Edit produk':'Tambah Barang'}><form className="formStack" onSubmit={e=>void saveProduct(e)}><label>SKU<input required value={productForm.sku} onChange={e=>setProductForm({...productForm,sku:e.target.value})}/></label><label>Nama<input required value={productForm.name} onChange={e=>setProductForm({...productForm,name:e.target.value})}/></label><label>Deskripsi<textarea value={productForm.description} onChange={e=>setProductForm({...productForm,description:e.target.value})}/></label><label>Barcode utama<input value={productForm.barcode} onChange={e=>setProductForm({...productForm,barcode:e.target.value})}/></label><label>Kategori<select value={productForm.categoryId} onChange={e=>setProductForm({...productForm,categoryId:e.target.value})}><option value="">Tanpa kategori</option>{categories.filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{categoryLabel(x)}</option>)}</select></label><label>Brand<select value={productForm.brandCode} onChange={e=>setProductForm({...productForm,brandCode:e.target.value})}><option value="">Tanpa brand</option>{refs.filter(x=>x.type==='BRAND'&&x.isActive).map(x=><option key={x.id} value={x.code}>{x.code} · {x.name}</option>)}</select></label><label>Base unit<select required value={productForm.unit} onChange={e=>setProductForm({...productForm,unit:e.target.value})}><option value="">Pilih base unit</option>{unitRefs.map(x=><option key={x.id} value={x.code}>{x.code} · {x.name}</option>)}</select><small>Gunakan satuan fisik terkecil yang benar-benar distok. Kemasan seperti bungkus/slop/lusin/renteng dibuat di Multi-UOM.</small></label><label>Tipe produk<select value={productForm.productType} onChange={e=>setProductForm({...productForm,productType:e.target.value})}><option value="PHYSICAL">PHYSICAL</option><option value="SERVICE">SERVICE</option></select></label><label>Harga modal<input required type="number" min="0" value={productForm.costPrice} onChange={e=>setProductForm({...productForm,costPrice:Number(e.target.value)})}/></label><label>Harga jual<input required type="number" min="0" value={productForm.salePrice} onChange={e=>setProductForm({...productForm,salePrice:Number(e.target.value)})}/></label><label>HET / harga eceran tertinggi<input type="number" min="0" value={productForm.retailCeilingPrice} onChange={e=>setProductForm({...productForm,retailCeilingPrice:e.target.value})} placeholder="Opsional"/></label><label>Minimum stok<input type="number" min="0" step="1" value={productForm.minStock} onChange={e=>setProductForm({...productForm,minStock:Math.max(0,Math.floor(Number(e.target.value)||0))})}/></label><label>Tax category<input value={productForm.taxCategoryCode} onChange={e=>setProductForm({...productForm,taxCategoryCode:e.target.value})} placeholder="Tax category"/></label><label className="checkboxRow"><input type="checkbox" checked={productForm.trackBatch} onChange={e=>setProductForm({...productForm,trackBatch:e.target.checked,trackExpiry:e.target.checked?productForm.trackExpiry:false})}/> Track batch</label><label className="checkboxRow"><input type="checkbox" checked={productForm.trackExpiry} onChange={e=>setProductForm({...productForm,trackExpiry:e.target.checked,trackBatch:e.target.checked?true:productForm.trackBatch})}/> Expiry wajib per batch</label><label className="checkboxRow"><input type="checkbox" checked={productForm.trackSerial} onChange={e=>setProductForm({...productForm,trackSerial:e.target.checked})}/> Serial tracking</label><label className="checkboxRow"><input type="checkbox" checked={productForm.allowNegativeStock} onChange={e=>setProductForm({...productForm,allowNegativeStock:e.target.checked})}/> Negative stock</label><label className="checkboxRow"><input type="checkbox" checked={productForm.isActive} onChange={e=>setProductForm({...productForm,isActive:e.target.checked})}/> Produk aktif</label><div className="actionRow">{canAll(editingProductId?'product.update':'product.create')&&<button>{editingProductId?'Simpan perubahan':'Simpan produk'}</button>}{editingProductId&&<button type="button" className="secondary" onClick={()=>{setEditingProductId(null);setProductForm({...emptyProduct,unit:unitRefs[0]?.code??''});}}>Batal edit</button>}</div></form><Table head={['SKU','Nama','Unit','Status','Aksi']} rows={products.map(x=>[<strong>{x.sku}</strong>,x.name,x.unit,<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canUpdateProduct&&<><button type="button" className="secondary" onClick={()=>editProduct(x)}>Edit produk</button><button type="button" className="secondary" onClick={()=>void toggleProduct(x)}>{x.isActive?'Nonaktifkan':'Aktifkan produk'}</button></>}</div>])} empty="Belum ada produk"/></Panel>}
   {(!mode || mode==='products') && <Panel eyebrow="VARIANT PRODUK" title={editingVariantId?'Edit Variant':'Variant / Opsi Produk'}><form className="formStack" onSubmit={e=>void saveVariant(e)}><label>Produk<select required value={variantForm.productId} onChange={e=>{setEditingVariantId(null);setVariantForm({...emptyVariant,productId:e.target.value});}}>{products.map(x=><option key={x.id} value={x.id}>{x.sku} · {x.name}</option>)}</select></label><label>Kode variant<input required value={variantForm.code} onChange={e=>setVariantForm({...variantForm,code:e.target.value})} placeholder="RED-L"/></label><label>SKU variant<input value={variantForm.sku} onChange={e=>setVariantForm({...variantForm,sku:e.target.value})}/></label><label>Nama variant<input required value={variantForm.name} onChange={e=>setVariantForm({...variantForm,name:e.target.value})} placeholder="Merah / Large"/></label><label>Attributes JSON<textarea value={variantForm.attributes} onChange={e=>setVariantForm({...variantForm,attributes:e.target.value})} placeholder='{"color":"Merah","size":"L"}'/></label><label>Harga modal override<input type="number" min="0" value={variantForm.costPrice} onChange={e=>setVariantForm({...variantForm,costPrice:e.target.value})}/></label><label>Harga jual override<input type="number" min="0" value={variantForm.salePrice} onChange={e=>setVariantForm({...variantForm,salePrice:e.target.value})}/></label><label className="checkboxRow"><input type="checkbox" checked={variantForm.isDefault} onChange={e=>setVariantForm({...variantForm,isDefault:e.target.checked})}/> Variant default</label><label className="checkboxRow"><input type="checkbox" checked={variantForm.isActive} onChange={e=>setVariantForm({...variantForm,isActive:e.target.checked})}/> Variant aktif</label><div className="actionRow">{canManageMasterData&&<button>Simpan variant</button>}{editingVariantId&&<button type="button" className="secondary" onClick={()=>{setEditingVariantId(null);setVariantForm({...emptyVariant,productId:variantForm.productId});}}>Batal</button>}</div></form><Table head={['Kode','Nama','SKU','Default','Status','Aksi']} rows={variantsFor(variantForm.productId).map(x=>[<strong>{x.code}</strong>,x.name,x.sku??'-',x.isDefault?'YA':'-',<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editVariant(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleVariant(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada variant"/></Panel>}
   {(!mode || mode==='products') && <Panel eyebrow="MULTI-UOM" title={editingUnitId?'Edit Satuan / Kemasan':'Satuan & Kemasan Produk'}><form className="formStack" onSubmit={e=>void saveUnit(e)}><label>Produk<select required value={unitForm.productId} onChange={e=>{setEditingUnitId(null);setUnitForm({...emptyUnit,productId:e.target.value});}}>{products.map(x=><option key={x.id} value={x.id}>{x.sku} · {x.name} · base {x.unit}</option>)}</select></label><label>Variant<select value={unitForm.variantId} onChange={e=>setUnitForm({...unitForm,variantId:e.target.value})}><option value="">Produk dasar</option>{variantsFor(unitForm.productId).filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><label>Unit / kemasan<select required value={unitForm.unitCode} onChange={e=>setUnitForm({...unitForm,unitCode:e.target.value})}><option value="">Pilih unit</option>{unitRefs.filter(x=>x.code!==products.find(p=>p.id===unitForm.productId)?.unit).map(x=><option key={x.id} value={x.code}>{x.code} · {x.name}</option>)}</select></label><label>Isi dalam base unit<input required type="number" min="2" step="1" value={unitForm.quantityFactor} onChange={e=>setUnitForm({...unitForm,quantityFactor:Math.max(2,Math.floor(Number(e.target.value)||2))})}/></label><label className="checkboxRow"><input type="checkbox" checked={unitForm.isDefaultSale} onChange={e=>setUnitForm({...unitForm,isDefaultSale:e.target.checked})}/> Default penjualan</label><label className="checkboxRow"><input type="checkbox" checked={unitForm.isDefaultPurchase} onChange={e=>setUnitForm({...unitForm,isDefaultPurchase:e.target.checked})}/> Default pembelian</label><label className="checkboxRow"><input type="checkbox" checked={unitForm.isActive} onChange={e=>setUnitForm({...unitForm,isActive:e.target.checked})}/> Unit aktif</label><div className="actionRow">{canManageMasterData&&<button>Simpan unit</button>}{editingUnitId&&<button type="button" className="secondary" onClick={()=>{setEditingUnitId(null);setUnitForm({...emptyUnit,productId:unitForm.productId});}}>Batal</button>}</div></form><Table head={['Variant','Unit','Isi base','Default','Status','Aksi']} rows={(unitCache[unitForm.productId]??[]).map(x=>[x.variant?.code??'Produk dasar',<strong>{x.unitCode}</strong>,String(x.quantityFactor),[x.isDefaultSale?'SALE':'',x.isDefaultPurchase?'PURCHASE':''].filter(Boolean).join(' / ')||'-',<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editUnit(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void toggleUnit(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada unit alternatif"/><p className="sectionHelp">Base unit tetap berasal dari master produk. Unit alternatif bersifat first-class dan menjadi sumber authoritative untuk faktor konversi barcode/harga.</p></Panel>}
   {(!mode || mode==='products') && <Panel eyebrow="BARCODE" title={editingBarcodeId?'Edit Barcode & Konversi':'Barcode & Konversi Unit'}><form className="formStack" onSubmit={e=>void saveBarcode(e)}><label>Produk<select required value={barcode.productId} onChange={e=>{const product=products.find(x=>x.id===e.target.value);setEditingBarcodeId(null);setBarcode({...barcode,productId:e.target.value,variantId:'',productUnitId:'',code:'',unitCode:product?.unit??'',quantityFactor:1,isPrimary:false});}}>{products.map(x=><option key={x.id} value={x.id}>{x.sku} · {x.name} · base {x.unit}</option>)}</select></label><label>Variant<select value={barcode.variantId} onChange={e=>setBarcode({...barcode,variantId:e.target.value,productUnitId:''})}><option value="">Produk dasar</option>{variantsFor(barcode.productId).filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><label>Barcode<input required value={barcode.code} onChange={e=>setBarcode({...barcode,code:e.target.value})}/></label><label>Multi-UOM<select value={barcode.productUnitId} onChange={e=>{const u=unitsFor(barcode.productId,barcode.variantId).find(x=>x.id===e.target.value);setBarcode({...barcode,productUnitId:e.target.value,unitCode:u?.unitCode??selectedBarcodeProduct?.unit??'',quantityFactor:u?.quantityFactor??1});}}><option value="">{selectedBarcodeProduct?.unit??'BASE'} · base unit</option>{unitsFor(barcode.productId,barcode.variantId).map(x=><option key={x.id} value={x.id}>{x.unitCode} · isi {x.quantityFactor}</option>)}</select></label><label>Isi per unit<input readOnly type="number" min="1" value={barcode.quantityFactor}/></label><label className="checkboxRow"><input type="checkbox" checked={barcode.isPrimary} onChange={e=>setBarcode({...barcode,isPrimary:e.target.checked})}/> Barcode utama</label><div className="actionRow">{canManageMasterData&&<button>{editingBarcodeId?'Simpan barcode':'Tambah barcode / konversi'}</button>}{editingBarcodeId&&<button type="button" className="secondary" onClick={()=>{setEditingBarcodeId(null);setBarcode(v=>({...v,code:'',quantityFactor:1,isPrimary:false}));}}>Batal</button>}</div></form><Table head={['Barcode','Variant','Unit','Faktor','Utama','Aksi']} rows={(barcodeCache[barcode.productId]??[]).map(x=>[<strong>{x.code}</strong>,x.variant?.code??'Produk dasar',x.productUnit?.unitCode??x.unitCode??selectedBarcodeProduct?.unit??'-',String(x.quantityFactor),x.isPrimary?'YA':'-',canManageMasterData?<button type="button" className="secondary" onClick={()=>editBarcode(x)}>Edit</button>:null])} empty="Belum ada barcode alternatif"/><p className="sectionHelp">Konversi unit tetap authoritative di ProductUnit. Barcode mengikat unit yang terdaftar dan dapat ditetapkan sebagai barcode utama.</p></Panel>}
   {(!mode || mode==='pricing') && <Panel eyebrow="PRICING" title={editingPriceId?'Edit Harga':'Harga Cabang / Segmen / Unit / Kuantitas'}><form className="formStack" onSubmit={e=>void savePrice(e)}><label>Produk<select required value={price.productId} onChange={e=>{const product=products.find(x=>x.id===e.target.value);setEditingPriceId(null);setPrice({...price,productId:e.target.value,variantId:'',productUnitId:'',unitCode:product?.unit??'',minQty:1,price:0,effectiveFrom:'',effectiveTo:'',isActive:true});}}>{products.map(x=><option key={x.id} value={x.id}>{x.sku} · {x.name}</option>)}</select></label><label>Variant<select value={price.variantId} onChange={e=>setPrice({...price,variantId:e.target.value,productUnitId:''})}><option value="">Produk dasar</option>{variantsFor(price.productId).filter(x=>x.isActive).map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><div className="formGrid"><label>Cabang<select value={price.branchId} onChange={e=>setPrice({...price,branchId:e.target.value})}><option value="">Semua cabang</option>{branches.map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></label><label>Segmen<input value={price.segmentCode} onChange={e=>setPrice({...price,segmentCode:e.target.value})}/></label></div><label>Unit harga<select value={price.productUnitId} onChange={e=>{const u=unitsFor(price.productId,price.variantId).find(x=>x.id===e.target.value);setPrice({...price,productUnitId:e.target.value,unitCode:u?.unitCode??selectedPriceProduct?.unit??''});}}><option value="">{selectedPriceProduct?.unit??'BASE'} · base unit</option>{unitsFor(price.productId,price.variantId).map(x=><option key={x.id} value={x.id}>{x.unitCode} · isi {x.quantityFactor}</option>)}</select></label><div className="formGrid"><label>Minimal qty<input type="number" min="1" step="1" value={price.minQty} onChange={e=>setPrice({...price,minQty:Math.max(1,Math.floor(Number(e.target.value)||1))})}/></label><label>Harga per unit jual<input required type="number" min="0" value={price.price} onChange={e=>setPrice({...price,price:Number(e.target.value)})}/></label></div><div className="formGrid"><label>Efektif mulai<input type="date" value={price.effectiveFrom} onChange={e=>setPrice({...price,effectiveFrom:e.target.value})}/></label><label>Efektif sampai<input type="date" value={price.effectiveTo} onChange={e=>setPrice({...price,effectiveTo:e.target.value})}/></label></div>{editingPriceId&&<label className="checkboxRow"><input type="checkbox" checked={price.isActive} onChange={e=>setPrice({...price,isActive:e.target.checked})}/> Harga aktif</label>}<div className="actionRow">{canManageMasterData&&<button>{editingPriceId?'Simpan perubahan harga':'Simpan harga'}</button>}{editingPriceId&&<button type="button" className="secondary" onClick={()=>{setEditingPriceId(null);setPrice(v=>({...v,minQty:1,price:0,effectiveFrom:'',effectiveTo:'',isActive:true}));}}>Batal</button>}</div></form><Table head={['Scope','Unit','Min Qty','Harga','Periode','Status','Aksi']} rows={(priceCache[price.productId]??[]).map(x=>[`${x.branch?.code??'ALL'} · ${x.segmentCode}`,x.productUnit?.unitCode??x.unitCode??selectedPriceProduct?.unit??'-',String(x.minQty),new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(x.price)),`${x.effectiveFrom?new Date(x.effectiveFrom).toLocaleDateString('id-ID'):'sekarang'} — ${x.effectiveTo?new Date(x.effectiveTo).toLocaleDateString('id-ID'):'∞'}`,<StatusChip status={x.isActive?'ACTIVE':'INACTIVE'}/>,<div className="actionRow">{canManageMasterData&&<><button type="button" className="secondary" onClick={()=>editPrice(x)}>Edit</button><button type="button" className="secondary" onClick={()=>void togglePrice(x)}>{x.isActive?'Nonaktifkan':'Aktifkan'}</button></>}</div>])} empty="Belum ada price rule"/><div className="panelTitle panelTitleSpaced"><div><span className="eyebrow">PRICE HISTORY</span><h2>Riwayat perubahan harga</h2></div><span>{(priceHistoryCache[price.productId]??[]).length} perubahan</span></div><Table head={['Waktu','Harga lama','Harga baru','Alasan']} rows={(priceHistoryCache[price.productId]??[]).map(x=>[new Date(x.changedAt).toLocaleString('id-ID'),x.oldSalePrice==null?'-':String(x.oldSalePrice),x.newSalePrice==null?'-':String(x.newSalePrice),x.reason??'-'])} empty="Belum ada riwayat harga"/></Panel>}
  </section>
  {msg&&<div className="notice">{msg}</div>}
 </>;
